  m0 : mat4x4<f32>,
  m1 : mat4x4<f32>,
  m2 : mat4x4<f32>,
  m3 : mat4x4<f32>,
  cascadeCount : u32,
  probePadA : u32,
  probePadB : u32,
  probePadC : u32,
